// PatientServiceHandler is an implementation of the healthcare.empi.v1.PatientService service.
type PatientServiceHandler interface {
	// SRS-EMPI-001. Issues the MRN from the registering facility's sequence.
	RegisterPatient(context.Context, *connect.Request[v1.RegisterPatientRequest]) (*connect.Response[v1.RegisterPatientResponse], error)
	// SRS-EMPI-003. Search before create, exact and fuzzy, with confidence.
	SearchPatients(context.Context, *connect.Request[v1.SearchPatientsRequest]) (*connect.Response[v1.SearchPatientsResponse], error)
	GetPatient(context.Context, *connect.Request[v1.GetPatientRequest]) (*connect.Response[v1.GetPatientResponse], error)
	UpdateDemographics(context.Context, *connect.Request[v1.UpdateDemographicsRequest]) (*connect.Response[v1.UpdateDemographicsResponse], error)
	// Moves a candidate to active once a positive identifier has been seen.
	ConfirmIdentity(context.Context, *connect.Request[v1.ConfirmIdentityRequest]) (*connect.Response[v1.ConfirmIdentityResponse], error)
	// SRS-EMPI-005. Merging is the most destructive operation here: a merge that
	// should not have happened produces a chart that reads as coherent, and is
	// found by a reaction rather than by a report. Restricted to authorised HIM.
	MergePatients(context.Context, *connect.Request[v1.MergePatientsRequest]) (*connect.Response[v1.MergePatientsResponse], error)
	// SRS-EMPI-006. Reverses a merge, or refuses with the reason it cannot.
	UnmergePatients(context.Context, *connect.Request[v1.UnmergePatientsRequest]) (*connect.Response[v1.UnmergePatientsResponse], error)
	// SRS-EMPI-004. The manual-review worklist thresholds route to.
	ListDuplicateCandidates(context.Context, *connect.Request[v1.ListDuplicateCandidatesRequest]) (*connect.Response[v1.ListDuplicateCandidatesResponse], error)
	DismissDuplicateCandidate(context.Context, *connect.Request[v1.DismissDuplicateCandidateRequest]) (*connect.Response[v1.DismissDuplicateCandidateResponse], error)
	// SRS-EMPI-011. External identifiers are linked and unlinked through an
	// adapter; neither direction deletes a row, because link and unlink history
	// is what makes a wrong link investigable.
	LinkIdentifier(context.Context, *connect.Request[v1.LinkIdentifierRequest]) (*connect.Response[v1.LinkIdentifierResponse], error)
	UnlinkIdentifier(context.Context, *connect.Request[v1.UnlinkIdentifierRequest]) (*connect.Response[v1.UnlinkIdentifierResponse], error)
	// Confirms an identifier linked while the issuing authority was unreachable.
	VerifyIdentifier(context.Context, *connect.Request[v1.VerifyIdentifierRequest]) (*connect.Response[v1.VerifyIdentifierResponse], error)
	// SRS-EMPI-012. An external source that disagrees with the record raises a
	// proposal; it never writes. A feed that can overwrite demographics will
	// eventually overwrite the right value with the wrong one, and nothing will
	// record what was lost.
	SubmitExternalDemographics(context.Context, *connect.Request[v1.SubmitExternalDemographicsRequest]) (*connect.Response[v1.SubmitExternalDemographicsResponse], error)
	// SRS-EMPI-017. A person asks for a correction; a reviewer decides. Raising
	// needs only read access, because the person asking is often the patient.
	RequestCorrection(context.Context, *connect.Request[v1.RequestCorrectionRequest]) (*connect.Response[v1.RequestCorrectionResponse], error)
	ListDemographicProposals(context.Context, *connect.Request[v1.ListDemographicProposalsRequest]) (*connect.Response[v1.ListDemographicProposalsResponse], error)
	// Applying or refusing is where the authority lives: deciding a proposal
	// needs the permission to change demographics, because that is what it does.
	ResolveDemographicProposal(context.Context, *connect.Request[v1.ResolveDemographicProposalRequest]) (*connect.Response[v1.ResolveDemographicProposalResponse], error)
	WithdrawDemographicProposal(context.Context, *connect.Request[v1.WithdrawDemographicProposalRequest]) (*connect.Response[v1.WithdrawDemographicProposalResponse], error)
	// SRS-EMPI-007. Names, preferences and relationships, effective-dated.
	RecordName(context.Context, *connect.Request[v1.RecordNameRequest]) (*connect.Response[v1.RecordNameResponse], error)
	GetPatientHistory(context.Context, *connect.Request[v1.GetPatientHistoryRequest]) (*connect.Response[v1.GetPatientHistoryResponse], error)
	RecordCommunicationPreference(context.Context, *connect.Request[v1.RecordCommunicationPreferenceRequest]) (*connect.Response[v1.RecordCommunicationPreferenceResponse], error)
	// SRS-EMPI-008. Recording a death stops routine scheduling; withdrawing one
	// exists because a registry feed can match the wrong record, and a system
	// that cannot undo it leaves somebody unable to book an appointment because
	// a computer believes they are dead.
	RecordDeceased(context.Context, *connect.Request[v1.RecordDeceasedRequest]) (*connect.Response[v1.RecordDeceasedResponse], error)
	ReverseDeceased(context.Context, *connect.Request[v1.ReverseDeceasedRequest]) (*connect.Response[v1.ReverseDeceasedResponse], error)
	// SRS-EMPI-009. Caregiver relationships, scoped and expiring.
	AddRelatedPerson(context.Context, *connect.Request[v1.AddRelatedPersonRequest]) (*connect.Response[v1.AddRelatedPersonResponse], error)
	VerifyRelatedPerson(context.Context, *connect.Request[v1.VerifyRelatedPersonRequest]) (*connect.Response[v1.VerifyRelatedPersonResponse], error)
	EndRelatedPerson(context.Context, *connect.Request[v1.EndRelatedPersonRequest]) (*connect.Response[v1.EndRelatedPersonResponse], error)
	GetCaregiverAuthority(context.Context, *connect.Request[v1.GetCaregiverAuthorityRequest]) (*connect.Response[v1.GetCaregiverAuthorityResponse], error)
}

